/** Typed access to src/data/charts.json (generated by scripts/convert_charts.py). */
import raw from "../data/charts.json";
import type { EventId, Gender, Profile } from "./model";

export interface Bracket {
  label: string;
  minAge: number | null;
  maxAge: number | null;
  /** values[p] = threshold to earn p points (seconds or reps); null where the chart is blank. */
  values: (number | null)[];
}

export interface EventChart {
  name: string;
  unit: "seconds" | "reps";
  better: "lower" | "higher";
  scoredBy: string;
  charts: Partial<Record<Gender | "all", Bracket[]>>;
}

export interface ChartsFile {
  generated: string;
  sources: string[];
  events: Record<EventId, EventChart>;
}

export const CHARTS = raw as unknown as ChartsFile;

/** One event's scoring table, resolved for a specific profile. */
export interface ScoreTable {
  event: EventId;
  better: "lower" | "higher";
  unit: "seconds" | "reps";
  bracket: Bracket;
  /** Which chart was used, e.g. "Men · 25 and under" or "Everyone". */
  chartLabel: string;
}

export function bracketForAge(brackets: Bracket[], age: number): Bracket {
  const match = brackets.find(
    (b) => (b.minAge === null || age >= b.minAge) && (b.maxAge === null || age <= b.maxAge),
  );
  if (match) return match;
  // Outside every range (should not happen with open-ended first/last columns): use the nearest end.
  const first = brackets[0];
  const last = brackets[brackets.length - 1];
  if (!first || !last) throw new Error("chart has no age brackets");
  return first.maxAge !== null && age <= first.maxAge ? first : last;
}

export function describeBracket(b: Bracket): string {
  if (b.minAge === null && b.maxAge === null) return "All ages";
  if (b.minAge === null) return `${b.maxAge} and under`;
  if (b.maxAge === null) return `${b.minAge} and over`;
  return `${b.minAge}–${b.maxAge}`;
}

/**
 * Which age columns apply, for hints like "mile 30 and under · push-ups and squats 25 and under".
 * Men's and women's charts share the same age columns, so gender isn't needed.
 */
export function ageBracketLabels(age: number): { mile: string; reps: string } {
  const mile = CHARTS.events.mile.charts.male;
  const reps = CHARTS.events.squats.charts.all;
  if (!mile || !reps) throw new Error("charts missing mile or squat brackets");
  return { mile: describeBracket(bracketForAge(mile, age)), reps: describeBracket(bracketForAge(reps, age)) };
}

export function tableFor(event: EventId, profile: Profile): ScoreTable {
  const chart = CHARTS.events[event];
  const byGender = chart.charts[profile.gender];
  const brackets = byGender ?? chart.charts.all;
  if (!brackets) throw new Error(`no chart for ${event}/${profile.gender}`);
  const bracket = bracketForAge(brackets, profile.age);
  const who = byGender ? (profile.gender === "male" ? "Men" : "Women") : "Everyone";
  const ages = describeBracket(bracket);
  return {
    event,
    better: chart.better,
    unit: chart.unit,
    bracket,
    chartLabel: ages === "All ages" ? who : `${who} · ${ages}`,
  };
}
